/bin/bash -lc "python3 -B -c 'import hashlib, pathlib; digest=lambda kind,data: hashlib.sha1(kind+b\" \"+str(len(data)).encode()+b\"\\0\"+data).digest();
for name in (\"base\", \"head\"):
 p=pathlib.Path(name)/\"slip.py\"
 blob=digest(b\"blob\",p.read_bytes())
 print(name, \"blob\",blob.hex(),\"tree\",digest(b\"tree\",b\"100644 slip.py\\0\"+blob).hex())'"
